CREATE TABLE tenant_department_members (id varchar(64) PRIMARY KEY,tenant_id varchar(64) NOT NULL,department_id varchar(64) NOT NULL,membership_id varchar(64) NOT NULL,is_primary boolean NOT NULL DEFAULT false,primary_membership_id varchar(64) GENERATED ALWAYS AS (CASE WHEN is_primary AND deleted_at IS NULL THEN membership_id ELSE NULL END) STORED,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY tenant_department_members_unique(tenant_id,department_id,membership_id),UNIQUE KEY tenant_department_members_primary_unique(tenant_id,primary_membership_id),KEY tenant_department_members_department_idx(tenant_id,department_id),KEY tenant_department_members_membership_idx(tenant_id,membership_id));
